import{_ as e,H as t,f as a,i}from"./chunks/framework.BH2BK_3i.js";const E=JSON.parse('{"title":"18 | 高密度：活在未来是一种怎样的活法？","description":"","frontmatter":{},"headers":[{"level":2,"title":"互动小茶桌","slug":"互动小茶桌","link":"#互动小茶桌","children":[]}],"relativePath":"超级访谈：对话道哥/18｜高密度：活在未来是一种怎样的活法？.md","filePath":"超级访谈：对话道哥/18｜高密度：活在未来是一种怎样的活法？.md","lastUpdated":1795560886000}'),_={name:"超级访谈：对话道哥/18｜高密度：活在未来是一种怎样的活法？.md"};function n(s,p,o,r,l,c){return t(),a("div",null,[...p[0]||(p[0]=[i('<h1 id="_18-高密度-活在未来是一种怎样的活法" tabindex="-1">18 | 高密度：活在未来是一种怎样的活法？ <a class="header-anchor" href="#_18-高密度-活在未来是一种怎样的活法" aria-label="Permalink to &quot;18 | 高密度：活在未来是一种怎样的活法？&quot;">​</a></h1><p>你好，我是晓蕾。</p><p>对于我来说，“活在未来”代表着预判能力和清醒感。但对于道哥，他说自己记性不好很健忘，活在未来的状态就是每天都在想未来是什么样子的。</p><p>一个每天都在想未来的人一定是很有目标感的。这不禁让我好奇，目标感极强的人是不是有那么一刻也会产生虚无感？也会有中年危机？</p><p>极客时间：为什么觉得自己是活在未来的人？</p><p>道哥：因为过去的事情我都忘了。我这个人有个习惯，不重要的事情我从来不去关心的，是否重要的判断是我自己来做的。这个习惯在生活上不太好，但是在工作上我觉得是好的。为什么我觉得我活在未来呢？因为我每天都在想未来是什么样子的。我天天想的就是这些，那自然就是活在未来。</p><p>回过头来看，过往很多事情，你不让我仔细去想，我其实压根就忘了，所以我不记仇，我只会记住对我有用的东西，一些其他的事情可能身边的同学就帮我处理掉了。</p><p>极客时间：感觉你的目标很明确，不管是小时候还是后面所有的环境影响，你是有抱负、有自己的使命感的。反过来，你有没有过所谓的虚无感或者无意义感的时刻？感觉到生命其实无意义？</p><p>道哥：比较少。这个就是人生观，人生观就是最后你要成为什么样的人，这是一个方向性的问题，以及终局的问题。</p><p>我是从小学开始天天在思考死亡的问题，小时候关于这个问题真的想太久了。一个人睡觉的时候也会思考，好多次想到自己以后会死，就会哭，然后会恐惧到哭着醒来。之后越想越可怕，就会睡不着。</p><p>一直到这些年，可能我也会每隔一两周就重新思考关于生死的问题，越想越透彻，反正觉得也没多少年好活了。我身边的一些人会很忌讳这个话题，但是我是相对看淡这个事情的，既然死亡是人不可回避的，那为什么不认真地去想一想、谈一谈这个问题，好好面对呢？其实我们会发现所有的宗教和哲学的系统到最后都是在帮助人更坦然地面对死亡这件事情。</p><p>你说关于迷茫的问题和困惑的问题，我认为我比别人走得更快一点，想清楚了人生观，想清楚了最后要成为什么样的人，就没那么困惑了。我有一次接受采访，说我这辈子也就干三件事情。第一件事情就是让智能时代更快到来。其他两件事是私事，陪伴好家人，教育好子女。我的前半生已经过完了，后半生一定是这三件事情。所以我为什么要把《计算》这本书写出来？我认为我写完这本书就没有什么遗憾了。我要沉淀和留下一点东西，我为这个世界留下最重要的东西就是这本书，不是别的。</p><p>人工智能是不是能干成我不知道，可能我这家企业也不一定成功，但是我们会尽所有的努力。如果它成功了，那是一个更好的事情。但是我现在这个阶段已经把自己的毕生所学全部浓缩在这本书里面了。这是我留给这个世界最好的礼物，哪怕我不在了，也会有人看这本书的，也会有更多人懂计算了。</p><p>极客时间：你有没有自己的人生有着超强的浓度或者密度更高的感觉？很多问题你不是不存在，而是你已经在很早的阶段，或者说比其他人在更早的阶段消耗掉了。你会有这种感受吗？</p><p>道哥：首先我认为自己的人生密度确实比别人大。我以前跟身边的同学说过，我觉得自己可能5 年活过了别人 20 年的经历，我的人生经历过很多事情，非常丰富。从这种丰富程度上来说，我的人生过得相当精彩。如果把人生看成一幅画卷的话，有的人是简笔画，我一定是一幅非常丰富多彩的油画。从人生密度上来讲，我够本了，前半生没有浪费时间。</p><p>但我希望后半生更精彩，所以从这个角度来讲，也不要给自己设限。举个例子，我活在牛顿的时代，我一定会想去见见他的。活在今天这个时代，我肯定要去见见马斯克。乔布斯没有赶上，他去世了。所以在这个时代还是要多做一点事情，多去一些地方，多见一些人，然后才算活过这一辈子。</p><p>从另外一个角度来讲，中年危机我觉得我也有的。一两年前，我在阿里也感受到了中年危机，所以我又赶快出来了。这是我解决焦虑的一种办法，就是消灭它，消灭焦虑的根源。</p><p>极客时间：其实你消灭焦虑的方法就是给自己更大的挑战。</p><p>道哥：对。现在我前半生过完了，人生只剩下一半。我是这么看我的人生的，这样就不会过得很焦虑，不会有任何浪费时间的想法，也不会允许自己去浪费时间。</p><p>极客时间：你怎么看待自己的中年危机？</p><p>道哥：我以前一直作为年轻的典型，遇到的所有人见我的第一面都是说“你这么年轻！”。我觉得自己首先吃了一个亏，长了一张娃娃脸。因为我去见一些领导和客户，他们会觉得这张脸跟大学生似的。实际上不是，我都是三十多岁的人了。现在我觉得身材保持得还可以，脸也没变形，多了很多白头发，多了一些斑点，整体看起来还是年轻的。但是我实际上快 40 岁了。</p><p>其实到了 35 岁以后，确实就进入到了中年危机的阶段，我认为这是身体上的变化带来的，身体的精力各方面会有点跟不上，会有点吃力和迟钝，肯定不像 20 岁的人。这个时候我就理解了什么是中年危机。中年危机是中年的生理变化带来的，自然而然就会有一些消极和怠慢甚至是躺平的想法。</p><p>所以我理解了为什么有一部分中年危机的人会选择躺平，那就像我之前说的，一个 24 岁的小孩能够自己做一个 Copilot，起码我认为它跟 Windows 官方要推出来的 Copilot 是高度类似的。但是可能有中年危机的人就不会有这种想法了。而且这类人可能会觉得要花一两千万才能搞出来。你就会很自然地发现，有中年危机是相当可怕的一件事情。</p><p>毕竟有钱了，有社会地位了，还有自己的小小的一摊，有小部门，那怎么可能去冒险呢？冒险可能就会失去所有，但是不冒险就很稳，这也是中年危机的另一种由来。年轻人，二十多岁，没有什么可以失去的，所以可以做任何事情，可以迎接任何挑战。光脚不怕穿鞋的，所以未来要堵在年轻人身上。</p><p>极客时间：咱们目前创业团队的年龄构成是怎样的？</p><p>道哥：我们年龄结构偏大了，所以我正在努力地去吸纳年轻人。</p><p>极客时间：其实也有很多中年人是勇往直前的。有的人很年轻，但是看起来很老，有的人已经很老，但其实很年轻。</p><p>道哥：是的，我同意的。浅雪跟我探讨过这个问题。她是不服老的，她说年轻人的定义就是看这个人还愿不愿意接纳新事物，愿不愿意学习新东西，看他是怎么表现的。我觉得这也是对的，但是今天如果从统计学上来说，我的结论也是成立的，我们只是讲了不同事物的不同方面而已。如果说不得罪人的话，年轻人是要看心态的。</p><p>极客时间：这种心态放到项目上，比如一些项目是 0-1 的，有的是 1-10 或者 1-99，这两类事情你会有偏好吗？</p><p>道哥：那我肯定喜欢从 0-1 的事情。这都是非常明确提出来的黑客守则：不要做重复性的体力劳动。我在小时候知道这个观念的时候就高度认可，所以我从来不做重复性的劳动。包括我在阿里云每次讲课的内容都不一样，就算会请我去讲同样的课程，我每次讲的东西也都会不一样，因为我完全接受不了重复，让我像背书一样把东西重新讲一遍很难。</p><p>极客时间：这个对于你创业会有什么影响吗？比如你会有意识地从 0-1 这个阶段开始？</p><p>道哥：我们会节节拔高的，因为每个阶段都会有更重要的事情去做，每件事情一定是让我倾注全部精力去做的。包括我在阿里这么多年，每年定目标的时候，也都是要突破的。</p><p>极客时间：或者这么说，你会定义每个阶段都是从 0-1，对吗？</p><p>道哥：因为每个阶段都需要自我突破的，不光是我自己本人，也包括整个公司，都是需要突破的。我一般是定十年的目标。我做一件事情，就会把决心下在十年这个时间范围，要花十年时间把这个事情做好。但是往往会提前，比如说 7 年就做好了。如果没有这种决心，我认为事情做不好的。</p><p>而且我们先把事情定成十年的目标，再去看中间所有可能会遇到的困难，其实也很简单了。这些事情放在十年的尺度上都不值得一提。</p><p>极客时间：有的时候其实我也希望能够把精力放在未来上，但是常常放不下过去，觉得自己过去的成长也很难忘，更害怕未来无法达成更大的成就。</p><p>道哥：我觉得这个是相对的。所谓的难忘，其实只是因为公司给了我们一个需要跳一跳才能够到的目标。我们始终在追这个目标，然后就成长了。或者说，我们的能力被训练过了。但这个是老板交代的，别人定义好的，我们错过的实际上是创造的机会，创造新事物的机会。</p><p>我不认为刚刚加入的应届生不具备做东西的能力，他们都具备定义从 0 到 1 的能力，但是他们就来错了地方。比如以前我们在读大学的时候，会觉得自己什么都能干，真的能干很多事情。我在读大学的时候也是这样的，做了很多事情，我做幻影是在读大学的时候，在阿里我也做不出一个幻影。</p><p>进入职场之后，我们以为来到了一个大公司，得到了高薪和社会的认可，实际上会发现自己能干的都是螺丝钉的事情。我还没离开阿里的时候，有一次跟一个 P5 的同学聊天，问他在公司的感受，他就说现在做什么事情好像都要先看一下做这个事情对不对。这就意味着他几乎什么都不能干了。一个 P5 的同学，那也就是应届毕业生，才毕业一两年，以前能干很多事情，现在只能干一点点事情。所以不是说他们不具备这个能力，是来错地方了。</p><p>极客时间：那我们应该给自己设定什么样的目标呢？我听说过一句话，不想做 CTO 的程序员不是好程序员，这个可能是大家普遍比较认可的一个目标。</p><p>道哥：我觉得这个目标不太对，是一个相当糟糕的目标。我觉得应该宣扬的目标是每个人都要有一个很成功的项目。这个项目可以是 GitHub 上有一个自己的项目，或者做了一个什么样的成功的产品，或者是发明了一项什么样的技术，要有一个很成功的东西。每个人应该有一个很成功的作品，而不是说自己要去成为一个 CTO。</p><p>现在很多公司的 CTO 是不懂技术的。有些情况下 CTO 甚至变成了一个官僚的职位，不是一个干活的职位。一旦这个 CTO 不写代码就很危险。如果 CTO 不写代码，那他很快就会变成一个谁都能干的岗位。</p><p>我的 CTO 是写代码的，她的梦想就是在一片海滩前面写代码，这是她的人生梦想。她端午假期的时候去外面玩了，给我发了一张照片说，她此刻正在对着大海写代码。当时还有一个我们的架构师也在对着大海写代码。他觉得同一时间干这么有情怀的事情，他很开心，这是他们的人生乐趣。</p><p>这是理想中的 CTO。CTO 不写代码，这个职位都没必要存在了，或者说 CTO 本来就是不应该存在的职位，这个职位应该叫做研发负责人。</p><h2 id="互动小茶桌" tabindex="-1">互动小茶桌 <a class="header-anchor" href="#互动小茶桌" aria-label="Permalink to &quot;互动小茶桌&quot;">​</a></h2><p>对于职场中的我们来说，未来这两个字意味着一种成长速度和具体的追求。既然生理上的中年危机不可避免，那我们唯一能做的就是保持激情，做心态上的年轻人。</p><p>在第 16 节的最后，我们讨论的问题是自己的追求是什么。这一节结束之后，有没有人让你产生更多的思考？</p><p>欢迎你在留言区和我们互动。如果有所启发，也欢迎把内容分享给更多的朋友一起交流学习。</p><p>下一节，我们聊一聊心态上的年轻人是怎么学习的。</p><p>戳此加入访谈交流群，和道哥一起探索工程师精神。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B6%85%E7%BA%A7%E8%AE%BF%E8%B0%88%EF%BC%9A%E5%AF%B9%E8%AF%9D%E9%81%93%E5%93%A5/images/18/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B6%85%E7%BA%A7%E8%AE%BF%E8%B0%88%EF%BC%9A%E5%AF%B9%E8%AF%9D%E9%81%93%E5%93%A5/images/18/1.png" alt=""></a></p>',51)])])}const d=e(_,[["render",n]]);export{E as __pageData,d as default};
